-- Notion 검토 사항 DB 스키마 (notion-create-database의 schema 인자에 그대로 사용)
-- 표시 규칙: docs/artifacts.md §10 (제목 = 화면 프레임 이름, 판정 = 검토 필요/승인, 카테고리 = Figma 구역 TAG)
-- '카테고리' 선택지는 notion-sync.json의 categories로, '필수 규칙' 선택지는 project.json notion.rule_options로 맞춘다.
CREATE TABLE ("검토 사항" TITLE, "검토 내용" RICH_TEXT COMMENT '한 줄 요약 (하네스)', "항목 ID" RICH_TEXT COMMENT '실행 간 유지되는 ID (하네스)', "판정" SELECT('검토 필요':red, '승인':green) COMMENT '하네스', "판정 유형" SELECT('문제 확인':red, '사람 판단 필요':yellow, '자료 부족':gray) COMMENT '하네스', "카테고리" MULTI_SELECT('분류 없음':default) COMMENT 'Figma 구역 TAG 기준 (하네스)', "프레임 태그" RICH_TEXT COMMENT 'Figma 프레임 TAG (하네스)', "단계" SELECT('S2 요구사항·흐름':blue, 'S3 컴포넌트':purple, 'S4 영향 분석':orange) COMMENT '하네스', "플랫폼" MULTI_SELECT('사용자앱':green, '관리자웹':brown) COMMENT '하네스', "영향 화면" RICH_TEXT COMMENT '프레임 이름 (하네스)', "필수 규칙" SELECT('규칙1':red, '규칙2':red, '해당 없음':default) COMMENT '하네스', "사유" RICH_TEXT COMMENT '하네스', "근거" RICH_TEXT COMMENT '프레임 이름·자료 절 (하네스)', "후속 조치" RICH_TEXT COMMENT '하네스', "수정 완료" CHECKBOX COMMENT '사용자 입력 — 하네스는 변경하지 않음', "컨펌 완료" CHECKBOX COMMENT '사용자 입력 — 하네스는 변경하지 않음', "결정 메모" RICH_TEXT COMMENT '사용자 입력 — 컨펌 완료 시 필수', "재검증 결과" SELECT('미실행':gray, 'PASS':green, '여전히 FAIL':red) COMMENT '하네스', "최근 실행" RICH_TEXT COMMENT 'run-id (하네스)', "정렬 순서" NUMBER COMMENT '프레임 번호 오름차순 정렬용 (하네스)', "확정 여부" SELECT('잠정 S2':gray, '잠정 S3':gray, '잠정 S4':yellow, '확정':green, '병합됨':brown) COMMENT '단계별 반영 상태 (하네스)')
-- 생성 후 기본 보기 (notion-update-view): 보드형, GROUP BY "카테고리"; SORT BY "정렬 순서" ASC
